sp_ListarCaixas	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarCaixas`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT\n\n        idCaixa,\n\n        idEmpresa,\n\n        usuario_open_id  AS idUsuarioAbertura,\n\n        usuario_close_id AS idUsuarioFechamento,\n\n        dthOpen          AS dthAbertura,\n\n        dthClose         AS dthFechamento,\n\n        saldoInicial,\n\n        saldoFinal,\n\n        saldoDinheiro,\n\n        saldoFinalContado,\n\n        diferenca,\n\n        obsEncerramento,\n\n        nomeOperador,\n\n        fAtivo\n\n    FROM Caixa\n\n    WHERE idEmpresa = p_idEmpresa\n\n    ORDER BY dthOpen DESC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
